using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("../build.binlog");

// Check which projects failed
Console.WriteLine("=== PROJECT RESULTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var project in projects)
{
    Console.WriteLine($"  {project.Name} ({project.ProjectFile})");
}

// Get all errors with full context
Console.WriteLine("\n=== ALL ERRORS ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var error in errors)
{
    Console.WriteLine($"[{error.ProjectFile}]");
    Console.WriteLine($"  File: {error.File}");
    Console.WriteLine($"  Line: {error.LineNumber}, Col: {error.ColumnNumber}");
    Console.WriteLine($"  Code: {error.Code}");
    Console.WriteLine($"  Text: {error.Text}");
    // Walk up to find parent project
    var parent = error.Parent;
    while (parent != null)
    {
        if (parent is Project p) { Console.WriteLine($"  Parent Project: {p.Name}"); break; }
        parent = parent.Parent;
    }
    Console.WriteLine();
}

// Check Api project - did it fail from cascading?
Console.WriteLine("\n=== LOOKING FOR CASCADING FAILURES ===");
var messages = build.FindChildrenRecursive<Message>();
foreach (var msg in messages)
{
    if (msg.Text != null && (msg.Text.Contains("previously failed") || msg.Text.Contains("not build") || msg.Text.Contains("dependency")))
        Console.WriteLine($"  {msg.Text}");
}
EOF
